engine.polishScan:
function polishScan(input) {
  var paras = (input && Array.isArray(input.paragraphs)) ? input.paragraphs : [];
  var HEDGE = /\b(perhaps|possibly|arguably|somewhat|rather|respectfully submit|we would submit|it would seem|it is our position|may wish|might wish|endeavou?r|desirous|at your earliest (?:possible )?convenience|if at all possible|in that regard|nevertheless|potentially)\b/gi;
  var DOUBLET = /\b(each and every|null and void|understood and agreed|terms and conditions|by and between|from and against|any and all|cease and desist|full and complete|true and correct|sole and exclusive|defend and hold harmless|various and sundry|numerous and repeated)\b/gi;
  var BLOAT = /\b(please be advised that|kindly be advised|it has come to our attention|we are in receipt of|revert back|with regards to|in order to|at this point in time|due to the fact that|notwithstanding the fact that|in the event that|aforementioned|heretofore|hereinafter|whatsoever|in point of fact|the undersigned|in respect thereof|as of yet)\b/gi;
  var PASSIVE = /\b(?:is|are|was|were|be|been|being)\s+(?:\w+ly\s+)?\w+(?:ed|en)\b/gi;

  function count(re, s) { var m = String(s).match(re); return m ? m.length : 0; }

  var out = [];
  paras.forEach(function (p, i) {
    var text = String((p && p.text != null ? p.text : p) || "").trim();
    var words = text ? text.split(/\s+/).filter(Boolean).length : 0;
    var item = {
      index: i,
      text: text,
      words: words,
      tags: [],
      score: 0,
      severity: "",
      needsWork: false,
    };
    // Structural boilerplate (dates, salutations, signature blocks, headings)
    // is short and has nothing to polish — skip without scoring.
    if (words < 12) { out.push(item); return; }

    var sentences = text.split(/(?<=[.!?])\s+/).filter(function (s) { return s.trim(); });
    var longest = 0;
    sentences.forEach(function (s) {
      var w = s.split(/\s+/).filter(Boolean).length;
      if (w > longest) longest = w;
    });
    var hedges = count(HEDGE, text);
    var doublets = count(DOUBLET, text);
    var bloat = count(BLOAT, text);
    var passive = count(PASSIVE, text);

    if (longest >= 35) item.tags.push(longest + "-word sentence");
    if (hedges) item.tags.push(hedges + " hedge" + (hedges === 1 ? "" : "s"));
    if (doublets) item.tags.push(doublets + " doublet" + (doublets === 1 ? "" : "s"));
    if (bloat) item.tags.push("redundancy ×" + bloat);
    if (passive >= 2) item.tags.push(passive + " passive");

    item.score =
      (longest >= 60 ? 4 : longest >= 45 ? 3 : longest >= 35 ? 2 : 0) +
      hedges * 1.5 + doublets * 1.5 + bloat * 1.2 + (passive >= 2 ? passive * 0.8 : 0);

    item.needsWork = item.score >= 2.5;
    item.severity = item.score >= 7 ? "Heavy" : item.score >= 4 ? "Moderate" : item.needsWork ? "Light" : "";
    out.push(item);
  });
  return { items: out, flagged: out.filter(function (i) { return i.needsWork; }) };
}

// Rewrite ONE highlighted fragment inside a version, using the whole
// version as context so the replacement fits its surroundings.
// mode: "regen" (same meaning, better wording) | "human" (less stuffy).

engine.polishFragment:
async function polishFragment(input, providers) {
  var fragment = String((input && input.fragment) || "");
  var ctx = String((input && input.context) || "");
  var mode = String((input && input.mode) || "regen");
  if (!fragment.trim()) throw new Error("Nothing highlighted.");

  var MODES = {
    regen:    "Rewrite it: same meaning, better wording.",
    human:    "Rewrite it so it sounds natural and human — plain, direct, unstuffy. Strip legalese, hedging and throat-clearing.",
    shorten:  "Make it materially shorter. Cut redundancy, doublets and filler while keeping every substantive point.",
    lengthen: "Expand it with more precision and detail, making implicit points explicit. Do NOT invent new facts, obligations, conditions or parties.",
    firmer:   "Make it firmer and more direct. Remove softeners and equivocation. Professional, not aggressive.",
    softer:   "Make it more conciliatory and diplomatic while leaving the substance unchanged.",
  };
  var styleLine = MODES[mode] || MODES.regen;

  var prompt =
    "You are editing ONE highlighted fragment inside a larger passage. Rewrite ONLY the fragment.\n\n" +
    styleLine + "\n" +
    "PRESERVE MEANING EXACTLY — no obligation, condition, exception, amount, date, defined term or " +
    "cross-reference may change, appear or disappear.\n" +
    "It must read naturally where it sits: match the surrounding tense, person, register and punctuation, " +
    "and do not repeat words that immediately precede or follow it.\n" +
    "Return ONLY the replacement text — no quotes, no preamble, no explanation, no trailing period unless " +
    "the fragment itself ended with one.\n\n" +
    "FULL PASSAGE (context only — do NOT return it):\n\"\"\"\n" + ctx + "\n\"\"\"\n\n" +
    "HIGHLIGHTED FRAGMENT TO REWRITE:\n\"\"\"\n" + fragment + "\n\"\"\"";

  var out = await providers.ai.complete(prompt, {
    thinkingBudget: 256,
    signal: input && input.signal,
  });
  return String(out || "").trim().replace(/^["“']+/, "").replace(/["”']+$/, "");
}

engine.polishAnalyze:
async function polishAnalyze(input, providers) {
  var original = String((input && input.text) || "");
  var instruction = String((input && input.instruction) || "").trim();
  // Surrounding document text, used only by the vocabulary-drift check.
  var docText = String((input && input.docText) || "");
  // Phrases the user marked as untouchable — negotiated wording that must
  // survive verbatim while everything around it is improved.
  var locked = (input && Array.isArray(input.locked) ? input.locked : [])
    .map(function (s) { return String(s || "").trim(); })
    .filter(Boolean);
  if (!original.trim()) {
    throw new Error("Nothing selected to polish.");
  }

  // ── Deterministic preservation check ─────────────────────────────────
  // Facts that MUST survive a meaning-preserving rewrite. Deliberately
  // high-signal only — exact tokens plus one structural test — because a
  // noisy guard trains people to ignore it.
  function _collect(s) {
    var out = [];
    function add(re, capIdx) {
      var m;
      re.lastIndex = 0;
      while ((m = re.exec(s)) !== null) {
        var v = capIdx != null ? m[capIdx] : m[0];
        if (v && String(v).trim()) out.push(String(v).trim());
        if (m.index === re.lastIndex) re.lastIndex++;
      }
    }
    // Proper thousands grouping — [\d,]+ would swallow a trailing comma
    // ("$50,000," from "…up to $50,000, except…") and then never match the
    // rewrite, producing a false "missing" on a perfectly good variant.
    add(/\$\s?\d{1,3}(?:,\d{3})*(?:\.\d{1,2})?/g);                       // money
    add(/\b\d+(?:\.\d+)?\s?(?:%|percent)\b/gi);                          // percentages
    add(/\b(?:Section|Article|Exhibit|Schedule|Appendix|Annex|Clause)\s+[A-Za-z0-9][A-Za-z0-9.\-]*/g); // cross-refs
    add(/\b(?:January|February|March|April|May|June|July|August|September|October|November|December)\s+\d{1,2},?\s+\d{4}\b/g); // dates
    add(/\b\d{1,3}(?:,\d{3})+\b/g);                                      // thousand-separated numbers
    add(/[“"]([^”"\n]{2,60})[”"]/g, 1);                                  // quoted defined terms (inner text)
    return out;
  }
  function _norm(s) {
    return String(s)
      .replace(/[“”]/g, '"')
      .replace(/[‘’]/g, "'")
      .replace(/\s+/g, " ")
      .trim()
      .toLowerCase();
  }
  // A dropped proviso is the dangerous silent failure (the rewrite reads
  // cleaner precisely because the carve-out is gone). Structural test:
  // original had exception language, rewrite has none at all.
  var EXCEPTION_RE = /\b(provided\s+that|provided,?\s*however|except|unless|excluding|other than|shall not apply|does not apply|save for|subject to|but not)\b/i;

  // Party/role designators. The classic silent drift is a rewrite that reads
  // fine but swaps the document's own vocabulary — "Supplier" becomes
  // "Vendor", "Purchaser" becomes "Buyer". Comparing the variant against the
  // WHOLE DOCUMENT (not just the selection) is the only way to see it.
  var ROLE_TERMS = [
    "Supplier", "Vendor", "Buyer", "Purchaser", "Seller", "Customer", "Client",
    "Contractor", "Subcontractor", "Company", "Licensor", "Licensee", "Lessor",
    "Lessee", "Landlord", "Tenant", "Employer", "Employee", "Consultant",
    "Provider", "Recipient", "Discloser", "Disclosing Party", "Receiving Party",
    "Manufacturer", "Distributor", "Reseller", "Affiliate", "Agreement", "Contract",
  ];
  function _hasWord(hay, word) {
    if (!hay || !word) return false;
    var esc = String(word).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    try { return new RegExp("\\b" + esc + "\\b", "i").test(hay); }
    catch (e) { return hay.indexOf(String(word).toLowerCase()) !== -1; }
  }
  // Terms the rewrite introduced that appear NOWHERE in the document.
  // A term already present in the user's own selection is never "drift" —
  // checking that explicitly also keeps the guard correct when the document
  // read fails or is truncated.
  function _vocabDrift(docText, variant, orig) {
    if (!docText) return [];
    var dn = _norm(docText), vn = _norm(variant), on = _norm(orig || "");
    var out = [];
    ROLE_TERMS.forEach(function (term) {
      var t = _norm(term);
      if (!_hasWord(vn, t)) return;   // not in the rewrite
      if (_hasWord(on, t)) return;    // came from the selection itself
      if (_hasWord(dn, t)) return;    // used elsewhere in the document
      out.push(term);
    });
    return out;
  }

  function _preservationCheck(orig, variant, docText) {
    var missing = [];
    var vn = _norm(variant);
    var seen = {};
    // Longest first, then drop any token contained in one already kept —
    // otherwise "$50,000" and "50,000" both report the same missing fact.
    var toks = _collect(orig).slice().sort(function (a, b) { return b.length - a.length; });
    var kept = [];
    toks.forEach(function (tok) {
      var key = _norm(tok);
      if (!key || seen[key]) return;
      for (var k = 0; k < kept.length; k++) {
        if (kept[k].indexOf(key) !== -1) return;   // substring of a longer token
      }
      seen[key] = true;
      kept.push(key);
      if (vn.indexOf(key) === -1) missing.push(tok);
    });
    var lostProviso = EXCEPTION_RE.test(orig) && !EXCEPTION_RE.test(variant);
    var introduced = _vocabDrift(docText, variant, orig);
    // Locked phrases must survive character-for-character (whitespace aside).
    var lockBroken = locked.filter(function (ph) {
      return vn.indexOf(_norm(ph)) === -1;
    });
    return {
      ok: missing.length === 0 && !lostProviso && introduced.length === 0 && lockBroken.length === 0,
      missing: missing,
      lostProviso: lostProviso,
      introduced: introduced,
      lockBroken: lockBroken,
    };
  }

  function _words(s) {
    var t = String(s || "").trim();
    return t ? t.split(/\s+/).filter(Boolean).length : 0;
  }

  // ── Prompt ───────────────────────────────────────────────────────────
  // input.only = one register label → regenerate just that card.
  // input.avoid = the version being replaced, so the retry differs.
  var REGISTERS = [
    ["Polished", "the same passage written well: better flow, no throat-clearing, run-ons split."],
    ["Plainer", "everyday wording, direct and readable, identical obligations."],
    ["Formal", "measured professional register, traditional drafting conventions, precise."],
  ];
  var only = String((input && input.only) || "").trim().toLowerCase();
  var avoid = String((input && input.avoid) || "").trim();
  var wanted = only
    ? REGISTERS.filter(function (r) { return r[0].toLowerCase() === only; })
    : REGISTERS;
  if (!wanted.length) wanted = REGISTERS;
  var single = wanted.length === 1;

  var prompt =
    "You are polishing a passage from a professional or legal document. Rewrite it " +
    (single ? "ONCE" : "THREE times") + ".\n\n" +
    "ABSOLUTE RULE — PRESERVE MEANING EXACTLY. Never add, remove, weaken or broaden an obligation, " +
    "condition, exception, carve-out, party, amount, date, defined term or cross-reference. You are " +
    "improving the WRITING, never the substance. Every proviso in the original must survive in all three.\n\n" +
    (single ? "Produce ONE version in this register:\n" : "Produce these three registers, in this order:\n") +
    wanted.map(function (r, i) {
      return "  " + (i + 1) + '. "' + r[0] + '" — ' + r[1];
    }).join("\n") + "\n\n" +
    (avoid
      ? ("You produced this before and the user rejected it. Produce a MEANINGFULLY DIFFERENT " +
         "rewrite — not a paraphrase of it:\n\"\"\"\n" + avoid + "\n\"\"\"\n\n")
      : "") +
    (instruction
      ? ("USER INSTRUCTION — apply to all three: " + instruction + "\n\n")
      : "") +
    (locked.length
      ? ("LOCKED PHRASES — these are negotiated wording. Reproduce each one VERBATIM, " +
         "character for character, in every version. Improve the writing AROUND them:\n" +
         locked.map(function (p) { return "  • " + p; }).join("\n") + "\n\n")
      : "") +
    "Each version must be a GENUINE rewrite — restructure sentences where it helps readability. " +
    "Do not merely swap one or two words. Keep the same number of paragraphs as the original and " +
    "separate paragraphs with a newline (\\n).\n\n" +
    "Return ONLY a JSON array, no markdown:\n" +
    "[" + wanted.map(function (r) {
      return '{"label":"' + r[0] + '","why":"<6 words max on what you changed>","text":"<the rewrite>"}';
    }).join(",") + "]\n\n" +
    "PASSAGE:\n\"\"\"\n" + original + "\n\"\"\"";

  // Writing is not deep reasoning — a small budget keeps Polish snappy.
  var raw = await providers.ai.completeJSON(prompt, null, {
    thinkingBudget: 512,
    strict: true,
    signal: input && input.signal,
  });

  var list = Array.isArray(raw)
    ? raw
    : (raw && Array.isArray(raw.versions) ? raw.versions : []);

  var origWords = _words(original);
  var variants = list.map(function (v) {
    var text = String((v && v.text) || "").trim();
    return {
      label: String((v && v.label) || "").trim() || "Polished",
      why: String((v && v.why) || "").trim(),
      text: text,
      words: _words(text),
      originalWords: origWords,
      check: _preservationCheck(original, text, docText),
    };
  }).filter(function (v) {
    // A rewrite identical to the input is not a rewrite. (Same lesson as
    // error_review's no-op findings — never surface a do-nothing option.)
    return v.text && _norm(v.text) !== _norm(original);
  });

  var toolVer = "unknown";
  try {
    if (typeof window !== "undefined" && window.eli && window.eli.tools &&
        window.eli.tools._loaded && window.eli.tools._loaded["polish"]) {
      toolVer = window.eli.tools._loaded["polish"].releasedAt || "unknown";
    }
  } catch (e) { /* tolerate */ }

  return {
    items: variants,
    overview: variants.length
      ? variants.length + " polished version(s) of " + origWords + " words."
      : "No usable rewrite was produced.",
    _meta: { original: original, instruction: instruction },
    provenance: {
      kernelVersion: (typeof window !== "undefined" && window.eli) ? window.eli.kernelVersion : "node",
      toolVersion: toolVer,
      promptVersion: "polish@v1",
      model: (typeof window !== "undefined" && window.eli && window.eli.ai &&
              typeof window.eli.ai.getModel === "function") ? window.eli.ai.getModel() : null,
      docHash: (input && input.docHash) || null,
      timestamp: Date.now(),
    },
  };
}

view.renderPolishBatchStart:
function renderPolishBatchStart(opts) {
  opts = opts || {};
  var host = opts.host;
  if (!host) return null;
  var UI = "Inter,'Segoe UI',system-ui,sans-serif";
  var GOLD = "#c9a227";

  function _el(tag, css, text) {
    var e = document.createElement(tag);
    if (css) e.style.cssText = css;
    if (text != null) e.textContent = text;
    return e;
  }
  function _sev(s) {
    if (s === "Heavy") return "background:#fdecec;color:#a92222;border:1px solid #f3c9c9;";
    if (s === "Moderate") return "background:#fffaf0;color:#8a6414;border:1px solid #ecd9a8;";
    return "background:#f4f6f9;color:#64748b;border:1px solid #e4e8ee;";
  }

  Array.prototype.slice.call(host.children).forEach(function (c) {
    if (c && c.id !== "_eli3_dashboard_root") host.removeChild(c);
  });
  var root = _el("div", "background:#f7f8fa;border:1px solid #e4e8ee;font-family:" + UI + ";");
  root.className = "_pl_root";
  host.appendChild(root);

  if (typeof opts.onBack === "function") {
    var backBar = _el("div", "padding:8px 18px;background:#fbfcfd;border-bottom:1px solid #edf0f4;");
    var backLink = _el("button", "background:none;border:none;padding:0;cursor:pointer;font:700 10px/1 " +
      UI + ";letter-spacing:.07em;text-transform:uppercase;color:#5b6472;", "← Ask ELI");
    backLink.type = "button";
    backLink.onclick = function () {
      try { if (root.parentNode) root.parentNode.removeChild(root); } catch (e) {}
      try { opts.onBack(); } catch (e) {}
    };
    backBar.appendChild(backLink);
    root.appendChild(backBar);
  }

  var hdr = _el("div", "padding:14px 18px 13px;background:#fff;border-bottom:2px solid " + GOLD + ";" +
    "display:flex;align-items:center;justify-content:space-between;gap:12px;");
  var hl = _el("div", "min-width:0;");
  hl.appendChild(_el("div", "font:800 8.5px/1 " + UI + ";letter-spacing:.24em;text-transform:uppercase;" +
    "color:" + GOLD + ";margin-bottom:6px;", "✨ Polish"));
  hl.appendChild(_el("div", "font:800 17px/1.15 " + UI + ";color:#0f172a;",
    (opts.total || 0) + " paragraphs selected"));
  hdr.appendChild(hl);
  hdr.appendChild(_el("div", "font:700 9.5px/1 " + UI + ";color:#64748b;background:#f4f6f9;" +
    "border:1px solid #e4e8ee;border-radius:10px;padding:5px 10px;white-space:nowrap;",
    (opts.words || 0) + " words"));
  root.appendChild(hdr);

  var body = _el("div", "padding:16px 18px 18px;");
  root.appendChild(body);

  var all = opts.items || [];
  var flagged = opts.flagged || all.filter(function (i) { return i.needsWork; });
  var lead = _el("div", "font:600 11.5px/1.5 " + UI + ";color:#334155;margin-bottom:11px;");
  lead.appendChild(_el("b", "color:#0f172a;", flagged.length
    ? (flagged.length + " of " + all.length + " look like they need work.")
    : "None look like they need work."));
  lead.appendChild(document.createTextNode("  Scanned instantly — no AI used yet."));
  body.appendChild(lead);

  var listBox = _el("div", "background:#fff;border:1px solid #e4e8ee;border-radius:3px;" +
    "box-shadow:0 1px 2px rgba(15,23,42,.04);margin-bottom:12px;");
  // Every selected paragraph is listed, in document order. Clean ones are
  // muted rather than hidden, so the scan is auditable — you can see what it
  // chose to skip instead of wondering where they went.
  all.forEach(function (it, i) {
    var work = !!it.needsWork;
    var row = _el("div", "display:flex;gap:11px;padding:11px 13px;" +
      (i === all.length - 1 ? "" : "border-bottom:1px solid #f0f2f5;") +
      (work ? "" : "background:#fcfcfd;"));
    row.appendChild(_el("span", "flex-shrink:0;width:20px;height:20px;border-radius:50%;" +
      (work ? "background:#0f172a;color:#fff;" : "background:#e7ebf0;color:#97a1af;") +
      "font:800 10px/20px " + UI + ";text-align:center;", String(i + 1)));
    var mid = _el("div", "min-width:0;flex:1;");
    var snip = String(it.text || "");
    if (snip.length > 118) snip = snip.slice(0, 118).replace(/\S+$/, "").trim() + "…";
    mid.appendChild(_el("div", "font:400 12.5px/1.55 Georgia,'Times New Roman',serif;color:" +
      (work ? "#334155" : "#a4adba") + ";", "“" + snip + "”"));
    if (work && (it.tags || []).length) {
      var tagWrap = _el("div", "");
      it.tags.forEach(function (t) {
        tagWrap.appendChild(_el("span", "display:inline-block;font:600 9.5px/1 " + UI + ";color:#6b7280;" +
          "background:#f4f6f9;border:1px solid #e4e8ee;border-radius:9px;padding:3px 7px;margin:4px 4px 0 0;", t));
      });
      mid.appendChild(tagWrap);
    }
    row.appendChild(mid);
    row.appendChild(_el("span", "flex-shrink:0;align-self:flex-start;font:800 8.5px/1 " + UI + ";" +
      "letter-spacing:.1em;text-transform:uppercase;padding:4px 7px;border-radius:2px;" +
      (work ? _sev(it.severity) : "background:#f4f6f9;color:#9aa3b0;border:1px solid #eceff3;"),
      work ? (it.severity || "Light") : "Looks fine"));
    listBox.appendChild(row);
  });
  body.appendChild(listBox);

  var go = _el("button", "width:100%;text-align:left;padding:13px 15px;cursor:pointer;" +
    "background:linear-gradient(180deg,#1a8a5c,#116844);border:1px solid #0d4f34;border-radius:3px;" +
    "box-shadow:inset 0 1px 0 rgba(255,255,255,.20),0 1px 3px rgba(15,23,42,.20);");
  go.type = "button";
  go.appendChild(_el("div", "font:800 11px/1 " + UI + ";letter-spacing:.07em;text-transform:uppercase;" +
    "color:#fff;margin-bottom:5px;", flagged.length
      ? ("→ Step through the " + flagged.length)
      : ("→ Step through all " + all.length + " anyway")));
  go.appendChild(_el("div", "font:500 11px/1.45 " + UI + ";color:#c9e7d8;",
    "Review and insert one at a time, in document order. Word follows along."));
  go.onclick = function () { if (typeof opts.onStart === "function") opts.onStart(); };
  body.appendChild(go);

  return { root: root };
}

view.renderPolishWorkspace:
function renderPolishWorkspace(opts) {
  opts = opts || {};
  var host = opts.host;
  if (!host) return null;

  var UI = "Inter,'Segoe UI',system-ui,sans-serif";
  var GOLD = "#c9a227";
  // Neutral buttons use the platinum gradient (project convention); the
  // single primary action is the only saturated control on the surface.
  var PLATINUM = "font:700 9.5px/1 " + UI + ";letter-spacing:.06em;text-transform:uppercase;" +
    "padding:7px 11px;color:#3b4757;background:linear-gradient(180deg,#ffffff,#e9edf2);" +
    "border:1px solid #c3ccd6;border-radius:2px;cursor:pointer;" +
    "box-shadow:inset 0 1px 0 #fff,0 1px 1.5px rgba(15,23,42,.07);";
  var PRIMARY = "font:800 10px/1 " + UI + ";letter-spacing:.09em;text-transform:uppercase;" +
    "padding:9px 17px;color:#fff;background:linear-gradient(180deg,#1a8a5c,#116844);" +
    "border:1px solid #0d4f34;border-radius:2px;cursor:pointer;" +
    "box-shadow:inset 0 1px 0 rgba(255,255,255,.20),0 1px 3px rgba(15,23,42,.20);";
  var CARD = "background:#fff;border:1px solid #e4e8ee;border-radius:3px;margin-bottom:14px;" +
    "box-shadow:0 1px 2px rgba(15,23,42,.04),0 10px 24px rgba(15,23,42,.055);overflow:hidden;";
  var PROSE = "font:400 15px/1.72 Georgia,'Times New Roman',serif;color:#111827;" +
    "padding:11px 14px;margin:2px 13px 0;border:1px solid transparent;border-radius:2px;" +
    "outline:none;white-space:pre-wrap;";
  var LAB = "font:800 9px/1 " + UI + ";text-transform:uppercase;letter-spacing:.16em;color:#0f172a;";
