    var revertBtn = _btn(PLATINUM + "margin-left:auto;color:#9a6a12;border-color:#e0cf9a;" +
      "background:linear-gradient(180deg,#fffdf6,#f6edd6);display:none;", "↺ Revert");
    actions.appendChild(useBtn);
    actions.appendChild(copyBtn);
    actions.appendChild(diffBtn);
    actions.appendChild(revertBtn);
    card.appendChild(actions);

    // Highlight inside this version → show the fragment toolbar. Deferred a
    // tick so the browser has finalised the selection before we measure it.
    prose.addEventListener("mouseup", function () {
      setTimeout(function () { _maybeShowBar(prose); }, 0);
    });
    prose.addEventListener("keyup", function () {
      setTimeout(function () { _maybeShowBar(prose); }, 0);
    });

    prose.addEventListener("input", function () {
      if (!edited) {
        edited = true;
        revertBtn.style.display = "";
        prose.style.background = "#fffdf6";
        prose.style.borderColor = "#e8dcb4";
      }
    });
    revertBtn.onclick = function () {
      prose.textContent = v.text;
      edited = false;
      revertBtn.style.display = "none";
      prose.style.background = "";
      prose.style.borderColor = "transparent";
    };
    diffBtn.onclick = function () {
      var showing = diffPane.style.display !== "none";
      if (showing) {
        diffPane.style.display = "none";
        prose.style.display = "";
        diffBtn.textContent = "⇄ Changes";
      } else {
        diffPane.innerHTML = _diffHtml(opts.original || "", prose.textContent || "");
        diffPane.style.display = "";
        prose.style.display = "none";
        diffBtn.textContent = "⇄ Hide";
      }
    };
    copyBtn.onclick = function () {
      var txt = prose.textContent || "";
      try {
        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(txt);
        } else if (window._eliClipboardWriteOrFallback) {
          window._eliClipboardWriteOrFallback(txt);
        }
        copyBtn.textContent = "✓ Copied";
        setTimeout(function () { copyBtn.textContent = "⧉ Copy"; }, 1400);
      } catch (e) { /* tolerate */ }
    };
    useBtn.onclick = function () {
      if (typeof opts.onUse !== "function") return;
      useBtn.disabled = true;
      useBtn.textContent = "Inserting…";
      Promise.resolve()
        .then(function () { return opts.onUse(prose.textContent || "", !!trackCb.checked, v); })
        .then(function () {
          useBtn.textContent = "✓ Inserted";
          useBtn.style.background = "linear-gradient(180deg,#e9f7ef,#d8efe2)";
          useBtn.style.color = "#12694a";
          useBtn.style.borderColor = "#a8d8c0";
          useBtn.style.boxShadow = "none";
        })
        .catch(function (err) {
          useBtn.disabled = false;
          useBtn.textContent = "⚠ Failed";
          if (typeof showToast === "function") {
            showToast("Insert failed: " + ((err && err.message) || "unknown"), "err");
          }
        });
    };
    return card;
  }

  function setVariants(variants) {
    listEl.innerHTML = "";
    var arr = variants || [];
    if (!arr.length) {
      listEl.appendChild(_el("div",
        CARD + "padding:18px;font:500 12.5px/1.6 " + UI + ";color:#6b7280;margin-bottom:14px;",
        "No usable rewrite came back. Try Regenerate, or add an instruction below."));
      guardLine.textContent = "";
      return;
    }
    _cards = [];
    arr.forEach(function (v, i) {
      var c = _card(v, i);
      _cards[i] = c;
      listEl.appendChild(c);
    });
    var bad = arr.filter(function (v) { return v.check && !v.check.ok; }).length;
    guardLine.textContent = bad
      ? ("⚠  " + bad + " of " + arr.length + " dropped something from the original")
      : ("✓  Meaning preserved in all " + arr.length);
    guardLine.style.color = bad ? "#a92222" : "#9aa3b0";
  }

  function setBusy(on, msg) {
    regenBtn.disabled = !!on;
    regenBtn.textContent = on ? (msg || "↻  Polishing…") : "↻  Regenerate";
    if (on) {
      listEl.innerHTML = "";
      var sk = _el("div", CARD + "padding:18px;");
      [86, 97, 64].forEach(function (w) {
        sk.appendChild(_el("div", "height:11px;width:" + w + "%;background:#eef1f5;border-radius:2px;" +
          "margin-bottom:10px;animation:_plPulse 1.1s ease-in-out infinite;"));
      });
      sk.appendChild(_el("div", "font:700 9.5px/1 " + UI + ";letter-spacing:.08em;text-transform:uppercase;" +
        "color:#9aa3b0;margin-top:4px;", msg || "Polishing…"));
      listEl.appendChild(sk);
      guardLine.textContent = "";
    }
  }

  return {
    setVariants: setVariants,
    setBusy: setBusy,
    getInstruction: function () { return instrInput.value || ""; },
  };
}

jsonTools.init:
function init(eli) {
  // v3 engine/view functions are stored on the bundle, NOT attached to
  // window (kernel evalBundle: "Stored on bundle for kernel dispatch; not
  // attached to window"). Resolve them here or every call is a ReferenceError.
  var bundle = eli.tools && eli.tools._loaded && eli.tools._loaded["polish"];
  if (!bundle) return;
  var polishAnalyze = bundle._eliEngineFns && bundle._eliEngineFns.polishAnalyze;
  var polishFragment = bundle._eliEngineFns && bundle._eliEngineFns.polishFragment;
  var polishScan = bundle._eliEngineFns && bundle._eliEngineFns.polishScan;
  var renderPolishWorkspace = bundle._eliViewFns && bundle._eliViewFns.renderPolishWorkspace;
  var renderPolishBatchStart = bundle._eliViewFns && bundle._eliViewFns.renderPolishBatchStart;
  if (!polishAnalyze || !renderPolishWorkspace) {
    if (eli.log && typeof eli.log.event === "function") {
      eli.log.event("tool", "polish_init_missing_fns", {
        engine: !!polishAnalyze, view: !!renderPolishWorkspace,
      });
    }
    return;
  }

  var _busy = false;

  // Capture the selection AND bookmark it, so the insert still lands after
  // the user has clicked around the taskpane and lost the live selection.
  function _readSelection() {
    return eli.host.runRaw("polish:read-selection", async function (context) {
      var sel = context.document.getSelection();
      sel.load("text");
      var paras = sel.paragraphs;
      paras.load("items");
      await context.sync();
      var text = String(sel.text || "");
      if (!text.trim()) return { text: "" };

      // Automatic list membership. Replacing the TEXT of a list item is safe,
      // but a multi-paragraph replacement inside one can spawn new list items
      // and renumber the document — worth warning about before inserting.
      var isList = false;
      try {
        var probes = [];
        for (var i = 0; i < paras.items.length; i++) {
          var li = paras.items[i].listItemOrNullObject;
          li.load("isNullObject");
          probes.push(li);
        }
        await context.sync();
        for (var j = 0; j < probes.length; j++) {
          if (probes[j] && !probes[j].isNullObject) { isList = true; break; }
        }
      } catch (e) { /* older host — leave false */ }

      // Bookmark names MUST begin with a letter — Word silently rejects
      // non-letter-leading names (insertBookmark becomes a no-op).
      var stamp = Date.now();
      var name = "ELI_POLISH_" + stamp;
      try { sel.insertBookmark(name); } catch (e) { name = ""; }
      // Per-paragraph bookmarks so batch mode can replace each one on its own.
      var plist = [];
      for (var pi = 0; pi < paras.items.length; pi++) {
        var pt = String(paras.items[pi].text || "");
        var pn = "ELI_POLISH_P" + stamp + "_" + pi;
        try { paras.items[pi].insertBookmark(pn); } catch (e) { pn = ""; }
        plist.push({ text: pt.replace(/\r\n?/g, "\n").trim(), bookmark: pn });
      }
      await context.sync();

      // Pending tracked changes make range.text a jumble of insertions AND
      // struck-through deletions ("the cust customer omer shall"). Polishing
      // that means rewriting garbage — use the POST-ACCEPT text instead.
      var hadRedlines = false;
      try {
        var helpers = eli.host && eli.host.helpers;
        if (helpers && typeof helpers.readResolvedText === "function") {
          var info = await helpers.readResolvedText(sel);
          if (info && info.hasRedlines && info.resolvedText) {
            text = String(info.resolvedText);
            hadRedlines = true;
          }
        }
      } catch (e) { /* fall back to the raw selection text */ }

      return {
        text: text, bookmark: name, hadRedlines: hadRedlines,
        isList: isList, paragraphs: plist,
      };
    });
  }

  // Capture the font of the LAST word of the target range. In a clause the
  // FIRST word is often a bold/underlined defined term, and insertText
  // inherits formatting from the range start — which would smear that
  // emphasis across the whole rewrite. The last word reflects body text.
  function _captureLastWordFont(range, ctx) {
    if (!range) return Promise.resolve(null);
    range.load("text");
    return ctx.sync().then(function () {
      var txt = String(range.text || "").trim();
      if (!txt) return null;
      var words = txt.split(/\s+/).filter(Boolean);
      var lastWord = String(words[words.length - 1] || "")
        .replace(/[.,;:!?\)\]\}”"']+$/g, "");   // Word searches plain text
      if (!lastWord) return null;
      var s = range.search(lastWord, { matchCase: true });
      s.load("items");
      return ctx.sync().then(function () {
        if (!s.items || !s.items.length) return null;
        var lw = s.items[s.items.length - 1];   // furthest right = the last word
        lw.load("font/bold,font/italic,font/underline,font/size,font/name,font/color");
        return ctx.sync().then(function () {
          return {
            bold: lw.font.bold, italic: lw.font.italic, underline: lw.font.underline,
            size: lw.font.size, name: lw.font.name, color: lw.font.color,
          };
        });
      });
    }).catch(function () { return null; });
  }

  function _insert(bookmark, newText, tracked) {
    return eli.host.runRaw("polish:insert", async function (context) {
      var prior = null;
      try {
        context.document.load("changeTrackingMode");
        await context.sync();
        prior = context.document.changeTrackingMode || null;
      } catch (e) { /* older builds — tolerate */ }
      var target = tracked ? "TrackAll" : "Off";
      try {
        context.document.changeTrackingMode = target;
        await context.sync();   // flush BEFORE the insert, or it lands in the old mode
      } catch (e) { /* tolerate */ }
      try {
        var range = null;
        if (bookmark) {
          range = context.document.getBookmarkRangeOrNullObject(bookmark);
          range.load("isNullObject");
          await context.sync();
          if (range.isNullObject) range = null;
        }
        if (!range) range = context.document.getSelection();
        var snap = await _captureLastWordFont(range, context);
        var inserted = range.insertText(newText, "Replace");
        await context.sync();
        // The whole selection was replaced, so the captured font applies to
        // all of it — no partial stamping needed.
        if (snap && inserted) {
          try {
            if (snap.name != null) inserted.font.name = snap.name;
            if (snap.size != null) inserted.font.size = snap.size;
            if (snap.bold != null) inserted.font.bold = snap.bold;
            if (snap.italic != null) inserted.font.italic = snap.italic;
            if (snap.underline != null) inserted.font.underline = snap.underline;
            if (snap.color != null) inserted.font.color = snap.color;
            await context.sync();
          } catch (e) { /* formatting is best-effort; the text landed */ }
        }
      } finally {
        if (prior != null && prior !== target) {
          try {
            context.document.changeTrackingMode = prior;
            await context.sync();
          } catch (e) { /* tolerate */ }
        }
      }
    });
  }

  // Whole-document text for the vocabulary-drift check. Init scope so both
  // the single and batch flows can use it.
  function _docText() {
    try {
      var c = (eli.host && typeof eli.host.cachedText === "function") ? eli.host.cachedText() : null;
      if (c && c.text && !c.stale) return Promise.resolve(String(c.text).slice(0, 120000));
    } catch (e) { /* fall through to a live read */ }
    if (eli.host && typeof eli.host.readText === "function") {
      return eli.host.readText({})
        .then(function (t) { return String(t || "").slice(0, 120000); })
        .catch(function () { return ""; });
    }
    return Promise.resolve("");
  }

  // Select + scroll to a bookmarked paragraph so the user sees where they are.
  function _selectBookmark(name) {
    if (!name) return Promise.resolve();
    return eli.host.runRaw("polish:locate", function (context) {
      var r = context.document.getBookmarkRangeOrNullObject(name);
      r.load("isNullObject");
      return context.sync().then(function () {
        if (r.isNullObject) return null;
        r.select();
        try { r.scrollIntoView(); } catch (e) {}
        return context.sync();
      });
    }).catch(function () { /* navigation is best-effort */ });
  }

  function _notice(host, text) {
    host.innerHTML = "";
    var d = document.createElement("div");
    d.style.cssText = "padding:22px 20px;background:#fff;border:1px solid #e5e7eb;" +
      "font:500 13px/1.65 Inter,'Segoe UI',system-ui,sans-serif;color:#6b7280;";
    d.textContent = text;
    host.appendChild(d);
  }

  function _backFn(cameFromAskEli) {
    if (!cameFromAskEli) return null;
    return function () {
      try {
        var ddr = document.getElementById("_eli3_dashboard_root");
        if (ddr) ddr.style.display = "";
      } catch (e) { /* tolerate */ }
      try { eli.dispatch("tile", "app_ask_eli"); } catch (e) { /* tolerate */ }
    };
  }

  // Batch: scan, show the start screen, then step the flagged paragraphs in
  // DOCUMENT ORDER, inserting as we go so stopping halfway leaves a coherent
  // document. No "polish as one passage" escape at this size — a 12-paragraph
  // single rewrite is exactly the unreviewable blob batch mode exists to avoid.
  function _startBatch(host, allParas, totalWords, cameFromAskEli) {
    var scan = polishScan({ paragraphs: allParas });
    var allItems = (scan && scan.items) || [];
    var back = _backFn(cameFromAskEli);
    // When nothing is flagged the user can still step through everything
    // substantive — better than a dead end telling them there's nothing to do.
    var flagged = (scan && scan.flagged && scan.flagged.length)
      ? scan.flagged
      : allItems.filter(function (i) { return i.words >= 12; });

    function _step(qi) {
      if (qi >= flagged.length) {
        _notice(host, "Finished — stepped through all " + flagged.length + " paragraph(s).");
        return;
      }
      var item = flagged[qi];
      var para = allParas[item.index] || {};
      var text = item.text;
      var instr = "", locks = [];
      _selectBookmark(para.bookmark);

      var ui = renderPolishWorkspace({
        host: host,
        original: text,
        wordCount: item.words,
        notices: [],
        progress: { current: qi + 1, total: flagged.length },
        onBack: back,
        onSkip: function () { _step(qi + 1); },
        onUse: function (newText, tracked) {
          return _insert(para.bookmark, String(newText || "").replace(/\n/g, "\r"), tracked)
            .then(function () {
              try { if (eli.stats) eli.stats.record("polishApplied"); } catch (e) {}
              try { if (eli.host && eli.host.invalidateCache) eli.host.invalidateCache(); } catch (e) {}
              setTimeout(function () { _step(qi + 1); }, 500);
            });
        },
        onRegenerate: function (i2, l2) { instr = i2 || ""; locks = l2 || []; _gen(); },
        onRegenOne: function (label, cur) {
          return _docText().then(function (dt) {
            return polishAnalyze({
              text: text, instruction: instr, docText: dt, locked: locks,
              only: label, avoid: cur,
            }, { ai: eli.ai, host: eli.host });
          }).then(function (r) { return (r && r.items && r.items[0]) || null; });
        },
        onInlineRegen: function (frag, full, mode) {
          if (!polishFragment) return Promise.reject(new Error("Fragment rewrite unavailable."));
          return polishFragment({ fragment: frag, context: full, mode: mode },
            { ai: eli.ai, host: eli.host });
        },
      });

      function _gen() {
        ui.setBusy(true, "Polishing…");
        _docText().then(function (dt) {
          return polishAnalyze({ text: text, instruction: instr, docText: dt, locked: locks },
            { ai: eli.ai, host: eli.host });
        }).then(function (r) {
          ui.setBusy(false);
          ui.setVariants((r && r.items) || []);
        }).catch(function (err) {
          ui.setBusy(false);
          ui.setVariants([]);
          if (typeof showToast === "function") {
            showToast("Polish failed: " + ((err && err.message) || "unknown"), "err");
          }
        });
      }
      _gen();
    }

    renderPolishBatchStart({
      host: host,
      total: allParas.length,
      words: totalWords,
      items: allItems,                                   // every selected paragraph
      flagged: (scan && scan.flagged) || [],             // the ones that scored
      onBack: back,
      onStart: function () { _step(0); },
    });
  }

  // openCtx.from identifies the caller. Only the Ask ELI panel gets a
  // "back" path — opening from the dashboard has nowhere to return to.
  async function showPolish(openCtx) {
    if (_busy) return;
    var cameFromAskEli = !!(openCtx && openCtx.from === "ask_eli");
    var host = (eli.ui && typeof eli.ui.claimOutput === "function")
      ? eli.ui.claimOutput()
      : document.getElementById("output");
    if (!host) return;

    var sel = null;
    try { sel = await _readSelection(); } catch (e) { sel = null; }
    if (!sel || !String(sel.text || "").trim()) {
      _notice(host, "Select the text you want to polish in the document, then click Polish again.");
      return;
    }

    // Word uses \r for paragraph marks; normalise for display + the AI, and
    // convert back on insert so paragraph breaks survive the round trip.
    var original = String(sel.text).replace(/\r\n?/g, "\n").trim();
    var wordCount = original.split(/\s+/).filter(Boolean).length;

    // More than one paragraph → batch. A single paragraph is one thought and
    // goes straight to the workspace.
    var allParas = (sel.paragraphs || []).filter(function (p) { return p.text; });
    if (allParas.length > 1 && polishScan) {
      return _startBatch(host, allParas, wordCount, cameFromAskEli);
    }

    // Current instruction/locks, so a single-card regen matches the others.
    var _lastInstruction = "";
    var _lastLocked = [];

    var notices = [];
    if (sel.hadRedlines) {
      notices.push({ kind: "info", text: "This selection has pending tracked changes — polishing the accepted (post-change) text." });
    }
    if (sel.isList) {
      notices.push({ kind: "warn", text: "Selection sits in an automatic list. Inserting replaces the text only; check numbering afterwards, especially for multi-paragraph rewrites." });
    }

    var ui = renderPolishWorkspace({
      host: host,
      original: original,
      wordCount: wordCount,
      notices: notices,
      onBack: cameFromAskEli ? function () {
        // claimOutput() hid the dashboard root on the way in; Ask ELI mounts
        // into it, so un-hide before reopening or it renders invisibly.
        try {
          var ddr = document.getElementById("_eli3_dashboard_root");
          if (ddr) ddr.style.display = "";
        } catch (e) { /* tolerate */ }
        try { eli.dispatch("tile", "app_ask_eli"); } catch (e) { /* tolerate */ }
      } : null,
      onUse: function (text, tracked) {
        var outText = String(text || "").replace(/\n/g, "\r");
        return _insert(sel.bookmark, outText, tracked).then(function () {
          try { if (eli.stats) eli.stats.record("polishApplied"); } catch (e) {}
          try {
            if (eli.activity && typeof eli.activity.add === "function") {
              eli.activity.add({
                type: "polish", icon: "✨", label: "Polish applied",
                summary: wordCount + " words rewritten" + (tracked ? " (tracked)" : ""),
                timestamp: Date.now(),
              });
            }
          } catch (e) {}
          try { if (eli.host && typeof eli.host.invalidateCache === "function") eli.host.invalidateCache(); } catch (e) {}
        });
      },
      onRegenerate: function (instruction, locked) { _run(instruction, locked); },
      // Regenerate ONE register, reusing the instruction/locks currently in
      // effect, and telling the model what it produced last so the retry
      // differs rather than paraphrasing itself.
      onRegenOne: function (label, currentText) {
        return _docText().then(function (docText) {
          return polishAnalyze(
            {
              text: original,
              instruction: _lastInstruction,
              docText: docText,
              locked: _lastLocked,
              only: label,
              avoid: currentText,
            },
            { ai: eli.ai, host: eli.host }
          );
        }).then(function (res) {
          return (res && res.items && res.items[0]) || null;
        });
      },
      // Highlight-to-regen inside a version: rewrite just that fragment,
      // with the full version supplied as context.
      onInlineRegen: function (fragment, fullText, mode) {
        if (!polishFragment) return Promise.reject(new Error("Fragment rewrite unavailable."));
        return polishFragment(
          { fragment: fragment, context: fullText, mode: mode },
          { ai: eli.ai, host: eli.host }
        );
      },
    });

    function _run(instruction, locked) {
      _lastInstruction = instruction || "";
      _lastLocked = locked || [];
      _busy = true;
      ui.setBusy(true, "Polishing…");
      Promise.resolve()
        .then(function () { return _docText(); })
        .then(function (docText) {
          return polishAnalyze(
            {
              text: original,
              instruction: instruction,
              docText: docText,
              locked: locked || [],
            },
            { ai: eli.ai, host: eli.host }
          );
        })
        .then(function (res) {
          ui.setBusy(false);
          ui.setVariants((res && res.items) || []);
        })
        .catch(function (err) {
          ui.setBusy(false);
          ui.setVariants([]);
          if (typeof showToast === "function") {
            showToast("Polish failed: " + ((err && err.message) || "unknown"), "err");
          }
        })
        .then(function () { _busy = false; });
    }

    _run("");
  }

  eli.register({
    tile: { app_polish: showPolish },
    // Cross-tool entry point — Ask ELI's "Polish Text" button dispatches this.
    polish: { open: showPolish },
  });
}

jsonTools.css:
/* tools/polish/style.css — states that cannot be inlined (:hover/:focus,
   keyframes, diff spans). Layout + colour live inline for guaranteed paint. */

._pl_root ._pl_card {
  transition: box-shadow .16s ease, transform .16s ease;
}
._pl_root ._pl_card:hover {
  box-shadow: 0 1px 2px rgba(15, 23, 42, .05), 0 14px 30px rgba(15, 23, 42, .085);
  transform: translateY(-1px);
}
._pl_root ._pl_prose:hover {
  background: #fbfcfd;
  border-color: #e9ecf1 !important;
}
._pl_root ._pl_prose:focus {
  background: #ffffff;
  border-color: #c9a227 !important;
  box-shadow: 0 0 0 3px rgba(201, 162, 39, .13);
}
._pl_root ._pl_instr:focus {
  background: #ffffff !important;
  border-color: #c9a227 !important;
  box-shadow: 0 0 0 3px rgba(201, 162, 39, .11);
}
._pl_root ._pl_del {
  color: #b3261e;
  text-decoration: line-through;
  text-decoration-thickness: 1px;
}
._pl_root ._pl_add {
  color: #146c43;
  text-decoration: underline;
  text-decoration-thickness: 1px;
}
._pl_root ._pl_menuitem:hover {
  background: #1f2a3a !important;
  filter: none;
}
._pl_root button:not(:disabled):hover {
  filter: brightness(1.03);
}
._pl_root button:not(:disabled):active {
  transform: translateY(1px);
}
._pl_root button:disabled {
  opacity: .62;
  cursor: default;
}
@keyframes _plPulse {
  0%, 100% { opacity: .42; }
  50%      { opacity: .82; }
}
